#!/usr/bin/env node
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve, basename, dirname, isAbsolute, posix } from "node:path";
import { deflateRawSync, inflateRawSync } from "node:zlib";
import { ensureDir, sha256Bytes, writeJson, readJson, assert } from "./lib/common.mjs";
function crc32(b){let c=0xffffffff;for(const x of b){c^=x;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0}
function safeName(name){assert(typeof name==="string"&&name.length,"Entry name required","ENTRY_NAME_INVALID");const n=name.replaceAll("\\","/");assert(!isAbsolute(name)&&!/^[A-Za-z]:\//.test(n),"Entry must be relative","ENTRY_NAME_ABSOLUTE");const x=posix.normalize(n);assert(x!=="."&&x!==".."&&!x.startsWith("../")&&!x.startsWith("/"),"Traversal prohibited","ENTRY_NAME_TRAVERSAL");return x}
function buildZip(entries){let off=0,locals=[],centrals=[];for(const e of entries){const name=safeName(e.name),nb=Buffer.from(name,"utf8"),raw=e.data,comp=deflateRawSync(raw),crc=crc32(raw),lh=Buffer.alloc(30);lh.writeUInt32LE(0x04034b50,0);lh.writeUInt16LE(20,4);lh.writeUInt16LE(0x0800,6);lh.writeUInt16LE(8,8);lh.writeUInt32LE(crc,14);lh.writeUInt32LE(comp.length,18);lh.writeUInt32LE(raw.length,22);lh.writeUInt16LE(nb.length,26);locals.push(lh,nb,comp);const ch=Buffer.alloc(46);ch.writeUInt32LE(0x02014b50,0);ch.writeUInt16LE(20,4);ch.writeUInt16LE(20,6);ch.writeUInt16LE(0x0800,8);ch.writeUInt16LE(8,10);ch.writeUInt32LE(crc,16);ch.writeUInt32LE(comp.length,20);ch.writeUInt32LE(raw.length,24);ch.writeUInt16LE(nb.length,28);ch.writeUInt32LE(off,42);centrals.push(ch,nb);off+=30+nb.length+comp.length}const central=Buffer.concat(centrals),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(central.length,12);end.writeUInt32LE(off,16);return Buffer.concat([...locals,central,end])}
function parseZip(buf){assert(buf.length>=22,"ZIP too short","ZIP_TRUNCATED");const eocd=buf.length-22;assert(buf.readUInt32LE(eocd)===0x06054b50,"EOCD missing","ZIP_EOCD_MISSING");const count=buf.readUInt16LE(eocd+10),centralSize=buf.readUInt32LE(eocd+12),centralOff=buf.readUInt32LE(eocd+16);assert(centralOff+centralSize===eocd,"Central directory bounds invalid","ZIP_CENTRAL_BOUNDS");const locals=[];let off=0;while(off<centralOff){assert(buf.readUInt32LE(off)===0x04034b50,"Local header missing","ZIP_LOCAL_HEADER");const flags=buf.readUInt16LE(off+6),method=buf.readUInt16LE(off+8),crc=buf.readUInt32LE(off+14),comp=buf.readUInt32LE(off+18),rawLen=buf.readUInt32LE(off+22),nl=buf.readUInt16LE(off+26),el=buf.readUInt16LE(off+28);assert(method===8&&(flags&0x0800),"ZIP method/UTF8 invalid","ZIP_FLAGS_INVALID");const name=safeName(buf.subarray(off+30,off+30+nl).toString("utf8")),start=off+30+nl+el,end=start+comp;assert(end<=centralOff,"Entry data crosses central dir","ZIP_ENTRY_BOUNDS");const data=inflateRawSync(buf.subarray(start,end));assert(data.length===rawLen&&crc32(data)===crc,"ZIP entry integrity failure","ZIP_ENTRY_INTEGRITY");locals.push({name,data,crc,comp,rawLen,offset:off});off=end}assert(locals.length===count,"Local count mismatch","ZIP_COUNT_MISMATCH");const central=[];off=centralOff;for(let i=0;i<count;i++){assert(buf.readUInt32LE(off)===0x02014b50,"Central header missing","ZIP_CENTRAL_HEADER");const crc=buf.readUInt32LE(off+16),comp=buf.readUInt32LE(off+20),rawLen=buf.readUInt32LE(off+24),nl=buf.readUInt16LE(off+28),el=buf.readUInt16LE(off+30),cl=buf.readUInt16LE(off+32),localOff=buf.readUInt32LE(off+42),name=safeName(buf.subarray(off+46,off+46+nl).toString("utf8"));central.push({name,crc,comp,rawLen,localOff});off+=46+nl+el+cl}assert(off===eocd,"Central size mismatch","ZIP_CENTRAL_SIZE");for(let i=0;i<count;i++){const a=locals[i],b=central[i];assert(a.name===b.name&&a.crc===b.crc&&a.comp===b.comp&&a.rawLen===b.rawLen&&a.offset===b.localOff,"Central/local mismatch","ZIP_DIRECTORY_MISMATCH")}assert(new Set(locals.map(x=>x.name)).size===locals.length,"Duplicate entries","ZIP_DUPLICATE_ENTRY");return locals}
function verifyManifest(entries){const map=new Map(entries.map(e=>[e.name,e.data]));assert(map.has("bundle-manifest.json"),"bundle-manifest.json missing","BUNDLE_MANIFEST_MISSING");const m=JSON.parse(map.get("bundle-manifest.json").toString("utf8"));for(const f of m.files||[]){assert(map.has(f.name),`Manifest entry missing ${f.name}`,"BUNDLE_ENTRY_MISSING");const d=map.get(f.name);assert(d.length===f.size&&sha256Bytes(d)===f.sha256,`Manifest hash/size mismatch ${f.name}`,"BUNDLE_HASH_MISMATCH")}return m}
function selfTest(){const b=buildZip([{name:"a b.txt",data:Buffer.from("x")}]);assert(parseZip(b)[0].name==="a b.txt","ZIP self-test");let f=false;try{buildZip([{name:"../x",data:Buffer.from("x")}])}catch(e){f=e.code==="ENTRY_NAME_TRAVERSAL"}assert(f,"Traversal test")}
const argv=process.argv.slice(2),get=n=>{const i=argv.indexOf(n);return i>=0?argv[i+1]:null};if(argv.includes("--self-test")){selfTest();console.log("PAYROLL_EVIDENCE_BUNDLE_SELF_TEST: PASS");process.exit(0)}const verify=get("--verify");if(verify){const e=parseZip(readFileSync(resolve(verify)));verifyManifest(e);console.log("PAYROLL_EVIDENCE_BUNDLE_VERIFY: PASS");process.exit(0)}
const mp=get("--manifest");assert(mp,"Usage: --manifest <json> | --verify <zip>","USAGE");const m=readJson(resolve(mp)),files=[],issues=[],seen=new Set();for(const f of m.files||[]){let name;try{name=safeName(f.name||basename(f.path));if(seen.has(name))throw Object.assign(new Error(`Duplicate ${name}`),{code:"ENTRY_NAME_DUPLICATE"});seen.add(name)}catch(e){issues.push({code:e.code||"ENTRY_NAME_INVALID",message:e.message});continue}const p=resolve(f.path);if(!existsSync(p)){if(f.required!==false)issues.push({code:"EVIDENCE_FILE_MISSING",path:p,name});continue}const data=readFileSync(p);files.push({name,data,sha256:sha256Bytes(data)})}if(issues.length){if(m.failureMatrix)writeJson(resolve(m.failureMatrix),issues);console.log("PAYROLL_EVIDENCE_BUNDLE: BLOCKED");process.exit(2)}const manifest={schemaVersion:"2.0",createdAt:new Date().toISOString(),files:files.map(x=>({name:x.name,sha256:x.sha256,size:x.data.length})),metadata:m.metadata||{}};const entries=[...files,{name:"bundle-manifest.json",data:Buffer.from(JSON.stringify(manifest,null,2)+"\n")}],bytes=buildZip(entries);verifyManifest(parseZip(bytes));const out=resolve(m.output);ensureDir(dirname(out));writeFileSync(out,bytes);verifyManifest(parseZip(readFileSync(out)));console.log(`PAYROLL_EVIDENCE_BUNDLE: PASS\nBUNDLE: ${out}`);
